    """Build PIN-capable capabilities advertising ``num_slots`` slots."""
    return LockCapabilities(
        supports_user_management=False,
        max_users=num_slots,
        credential_types={
            CredentialType.PIN: CredentialTypeCapability(
                num_slots=num_slots,
                min_length=4,
                max_length=8,
                supports_learn=False,
            )
        },
    )


